17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
37	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
38	import org.springframework.samples.petclinic.rest.controller.InvalidTelephoneException;
39	import org.springframework.samples.petclinic.rest.controller.RequiredFieldsMissingException;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
66	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
67	     */
68	    private static final Pattern EMAIL_PATTERN =
69	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        rejectMissingOrBlankFields(ownerFieldsDto);
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
121	        owner.setEmail(normalizeEmail(owner.getEmail()));
122	        if (owner.getRegistrationDate() == null) {
123	            owner.setRegistrationDate(LocalDate.now());
124	        }
125	        rejectDuplicateTelephone(owner.getTelephone());
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
136	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
137	        if (currentOwner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        currentOwner.setAddress(ownerFieldsDto.getAddress());
141	        currentOwner.setCity(ownerFieldsDto.getCity());
142	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
143	        currentOwner.setLastName(ownerFieldsDto.getLastName());
144	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
145	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
146	        this.clinicService.saveOwner(currentOwner);
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Transactional
152	    @Override
153	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        this.clinicService.deleteOwner(owner);
159	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        HttpHeaders headers = new HttpHeaders();
170	        Pet pet = petMapper.toPet(petFieldsDto);
171	        owner.setId(ownerId);
172	        pet.setOwner(owner);
173	        pet.getType().setName(null);
174	        this.clinicService.savePet(pet);
175	        PetDto petDto = petMapper.toPetDto(pet);
176	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
177	            .buildAndExpand(pet.getId()).toUri());
178	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
184	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
185	        if (currentOwner != null) {
186	            Pet currentPet = this.clinicService.findPetById(petId);
187	            if (currentPet != null) {
188	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
189	                currentPet.setName(petFieldsDto.getName());
190	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
191	                this.clinicService.savePet(currentPet);
192	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
193	            }
194	        }
195	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
201	        HttpHeaders headers = new HttpHeaders();
202	        Visit visit = visitMapper.toVisit(visitFieldsDto);
203	        Pet pet = new Pet();
204	        pet.setId(petId);
205	        visit.setPet(pet);
206	        this.clinicService.saveVisit(visit);
207	        VisitDto visitDto = visitMapper.toVisitDto(visit);
208	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
209	            .buildAndExpand(visit.getId()).toUri());
210	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
211	    }
212	
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
217	        Owner owner = this.clinicService.findOwnerById(ownerId);
218	        if (owner != null) {
219	            Pet pet = owner.getPet(petId);
220	            if (pet != null) {
221	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
222	            }
223	        }
224	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
225	    }
226	
227	    /**
228	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
229	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
230	     *
231	     * @param fields the submitted owner fields
232	     * @throws RequiredFieldsMissingException if any of firstName, lastName, address, city or telephone is
233	     *                                        {@code null} or blank
234	     */
235	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
236	        List<String> missing = new ArrayList<>();
237	        if (isBlank(fields.getFirstName())) {
238	            missing.add("firstName");
239	        }
240	        if (isBlank(fields.getLastName())) {
241	            missing.add("lastName");
242	        }
243	        if (isBlank(fields.getAddress())) {
244	            missing.add("address");
245	        }
246	        if (isBlank(fields.getCity())) {
247	            missing.add("city");
248	        }
249	        if (isBlank(fields.getTelephone())) {
250	            missing.add("telephone");
251	        }
252	        if (!missing.isEmpty()) {
253	            throw new RequiredFieldsMissingException(missing);
254	        }
255	    }
256	
257	    private boolean isBlank(String value) {
258	        return value == null || value.isBlank();
259	    }
260	
261	    /**
262	     * Normalizes a submitted telephone number by removing every non-digit character and requiring the
263	     * result to be exactly ten digits, which becomes the stored and returned value.
264	     *
265	     * @param telephone the raw telephone value from the request
266	     * @return the 10-digit, digits-only telephone
267	     * @throws InvalidTelephoneException if the stripped value is not exactly ten digits
268	     */
269	    private String normalizeTelephone(String telephone) {
270	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
271	        if (digits.length() != 10) {
272	            throw new InvalidTelephoneException(digits);
273	        }
274	        return digits;
275	    }
276	
277	    /**
278	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
279	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
280	     * lower-cased.
281	     *
282	     * @param email the raw email value from the request, or {@code null} if omitted
283	     * @return the lower-cased email, or {@code null} if none was supplied
284	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
285	     */
286	    private String normalizeEmail(String email) {
287	        if (email == null) {
288	            return null;
289	        }
290	        String trimmed = email.strip();
291	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
292	            throw new InvalidEmailException(email);
293	        }
294	        return trimmed.toLowerCase(Locale.ROOT);
295	    }
296	
297	    /**
298	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
299	     * their telephone in normalized (digits-only) form, so an exact string comparison is sufficient.
300	     *
301	     * @param telephone the normalized telephone of the owner being created
302	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
303	     */
304	    private void rejectDuplicateTelephone(String telephone) {
305	        boolean taken = this.clinicService.findAllOwners().stream()
306	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
307	        if (taken) {
308	            throw new DuplicateTelephoneException(telephone);
309	        }
310	    }
311	}
